               B('You could have called.', ['Tu', 'aurais', 'pu', 'téléphoner.'], 'as', 'could have = aurais pu.', 'tu <b>aurais pu</b>.'),
               B('She would have liked to come.', ['Elle', 'aurait', 'aimé', 'venir.'], 'serait', 'aimer takes avoir.', 'elle <b>aurait aimé</b>.'),
               B('They would have gone.', ['Ils', 'seraient', 'allés.'], 'auraient', 'aller takes être.', 'ils <b>seraient allés</b>.'),
